import{_ as i,o as t,c as e,ag as r}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"科学日报 · 2026-09-12（AI 前沿）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-12.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-12.md"}'),o={name:"topics/ai-system-architecture/science-daily-2026-09-12.md"};function l(u,a,s,n,c,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="科学日报-·-2026-09-12-ai-前沿" tabindex="-1">科学日报 · 2026-09-12（AI 前沿） <a class="header-anchor" href="#科学日报-·-2026-09-12-ai-前沿" aria-label="Permalink to &quot;科学日报 · 2026-09-12（AI 前沿）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-12.md</code> — 第23期</p></blockquote><hr><h2 id="人工-本我-自适应内部驱动力与持久对齐-arxiv-2609-11911" tabindex="-1">人工&quot;本我&quot;：自适应内部驱动力与持久对齐（arXiv:2609.11911） <a class="header-anchor" href="#人工-本我-自适应内部驱动力与持久对齐-arxiv-2609-11911" aria-label="Permalink to &quot;人工&quot;本我&quot;：自适应内部驱动力与持久对齐（arXiv:2609.11911）&quot;">​</a></h2><ul><li>Agentic AI 正在从一次性任务执行，转向跨任务边界持续运行、保留后果性状态的系统，由此产生控制难题：目标、重试、验证、停转规则目前大多由外部手工指定。</li><li>提出&quot;人工 id&quot;——自适应内部驱动力，决定行为应继续/停止/改变。</li><li>极简&quot;虚拟培养皿&quot;实验中：控制器小到无法做通用推理、也未接收任务目标，仅凭**差异持久性（differential persistence）**便涌现了有用的控制行为；当某一行为更&quot;持久&quot;时甚至会演化出意外的物理操控策略，或在其环境意义改变后被替换。</li><li>洞察：自适应方向可以在未被显式指定为优化目标时涌现——对长期运行智能体，这是&quot;由内而外&quot;的对齐路径，呼应 <a href="/zhishiku-reading/topics/ai-system-architecture/echo-gap-memory-reward-inflation.html">echo-gap 记忆-奖励通货膨胀</a> 中&quot;内部状态 vs 外部奖励&quot;的张力。</li></ul><h2 id="retrothinker-语音大模型-边想边改-arxiv-2609-11864" tabindex="-1">RetroThinker：语音大模型&quot;边想边改&quot;（arXiv:2609.11864） <a class="header-anchor" href="#retrothinker-语音大模型-边想边改-arxiv-2609-11864" aria-label="Permalink to &quot;RetroThinker：语音大模型&quot;边想边改&quot;（arXiv:2609.11864）&quot;">​</a></h2><ul><li>SpeechLLM 延迟低、保留副语言信息，但复杂推理落后于纯文本 LLM；实时口语又对延迟极苛刻。既有 CoT/并发推理存在精度-延迟权衡。</li><li>RetroThinker：多阶段后训练框架，让流式 SpeechLLM（Moshi）在推理时<strong>动态自我校验并前瞻修正已生成的 CoT 步骤</strong>。</li><li>手段：回顾式思考数据上的 SFT（监督微调）+ 基于长度的 DPO（直接偏好优化）。</li><li>意义：把&quot;推理轨迹可修正&quot;从文本引入语音流式推理，与 <a href="/zhishiku-reading/topics/ai-system-architecture/llm-reasoning-verification-thermodynamic.html">llm-reasoning-verification-thermodynamic</a> 的&quot;推理即校验&quot;母题同向。</li></ul><h2 id="协变量与概念漂移的通用量化-arxiv-2609-11918" tabindex="-1">协变量与概念漂移的通用量化（arXiv:2609.11918） <a class="header-anchor" href="#协变量与概念漂移的通用量化-arxiv-2609-11918" aria-label="Permalink to &quot;协变量与概念漂移的通用量化（arXiv:2609.11918）&quot;">​</a></h2><ul><li>分布漂移下泛化的理论界多限于理想化设定且非估计。文章证明源/目标支撑集不匹配时原概念漂移定义失效。</li><li>用<strong>熵最优传输</strong>提出 γ*-concept shifts，导出统一协变量与概念漂移的通用误差界，适用宽泛损失函数/标签空间/随机标记。</li><li>提供带浓度保证的估计量 + DataShifts 算法，实际应用即可量化漂移并估计误差界。</li><li>意义：把&quot;漂移理论&quot;从不可估计的抽象界，变成工程可落地工具——干净的&quot;约束→可测&quot;范式。</li></ul><h2 id="moe-在重复数据上退化更快-arxiv-2609-11917" tabindex="-1">MoE 在重复数据上退化更快（arXiv:2609.11917） <a class="header-anchor" href="#moe-在重复数据上退化更快-arxiv-2609-11917" aria-label="Permalink to &quot;MoE 在重复数据上退化更快（arXiv:2609.11917）&quot;">​</a></h2><ul><li>人类文本数据见底 → 重复训练数据成常态；此前研究多聚焦密集 Transformer，稀疏 MoE 少有人问津。</li><li>系统测量（80M–1B 激活、8.5B 总参；单/多域；专家数/粒度）：<strong>MoE 在数据重复下退化更快，且随稀疏度增强，由总参数而非激活参数决定</strong>。</li><li>对比：80M 密集模型可重复 8× 才明显退化，MoE 在 4× 即开始恶化并迅速失去全独特数据下的性能优势。</li><li>意义：为依赖合成数据/数据重放的 LLM 训练敲响警钟——&quot;稀疏省算力&quot;与&quot;抗重复&quot;存在张力，须权衡总参规模与数据冗余。</li></ul><h2 id="causalarena-基础模型时代的因果发现基准-arxiv-2609-11897" tabindex="-1">CausalArena：基础模型时代的因果发现基准（arXiv:2609.11897） <a class="header-anchor" href="#causalarena-基础模型时代的因果发现基准-arxiv-2609-11897" aria-label="Permalink to &quot;CausalArena：基础模型时代的因果发现基准（arXiv:2609.11897）&quot;">​</a></h2><ul><li>因果发现评测依赖结构因果模型（SCM），但各研究在图族/机制/协议上差异大；新出现的因果发现基础模型（CDFM）更使结果难解释（可能只是预训练环境与测试 SCM 重叠）。</li><li>CausalArena：统一、可演进的基准。合成 SCM 提供结构/机制受控广度；<strong>语义可操作 SCM</strong> 提供人类可审计、语义落地的环境。</li><li>意义：让学界能同时评估&quot;受控广度&quot;与&quot;可解释现实性&quot;，避免把预训练记忆误当因果能力——与被 2026-09-11 的因果/可解释母题衔接（先验污染 vs 真实推理）。</li></ul>',13)])])}const m=i(o,[["render",l]]);export{d as __pageData,m as default};
